import { opendir, lstat } from 'node:fs/promises';
import { join, relative, sep } from 'node:path';
export interface FileEntry { relativePath: string; absolutePath: string; size: number; mtimeNs: bigint; mode: number; }
export async function scan(root: string): Promise<FileEntry[]> {
  const files: FileEntry[] = [];
  async function visit(directory: string): Promise<void> {
    for await (const entry of await opendir(directory)) {
      if (entry.name === '.git' || entry.name === '.driftship') continue;
      const absolutePath = join(directory, entry.name);
      const info = await lstat(absolutePath, { bigint: true });
      if (info.isSymbolicLink()) continue;
      if (info.isDirectory()) { await visit(absolutePath); continue; }
      if (!info.isFile()) continue;
      files.push({ relativePath: relative(root, absolutePath).split(sep).join('/'), absolutePath,
        size: Number(info.size), mtimeNs: info.mtimeNs, mode: Number(info.mode) });
    }
  }
  await visit(root);
  files.sort((a,b) => a.relativePath.localeCompare(b.relativePath, 'en'));
  return files;
}

