import { scan } from './scan.ts';
import { uploadFile } from './http.ts';
export async function push(options: PushOptions): Promise<PushResult> {
  const files = await scan(options.directory);
  const receipts = [];
  for (const file of files) {
    options.signal.throwIfAborted();
    if (!options.dryRun) receipts.push(await uploadFile(options.destination, file, options.token, options.signal));
  }
  return { files: files.length, bytes: files.reduce((sum,file) => sum+file.size,0), receipts };
}

