import { mkdir, open, readFile, rename, unlink } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';
export interface JournalPart { number:number; bytes:number; sha256:string; }
export interface JournalFile { path:string; size:number; mtimeNs:string; sha256:string; uploadId:string; chunkBytes:number; parts:JournalPart[]; receipt?:Receipt; }
export interface Journal { version:1; destination:string; files:Record<string,JournalFile>; }
export async function readJournal(path:string):Promise<Journal|undefined> {
  let body:string;
  try { body=await readFile(path,'utf8'); }
  catch(error) { if((error as NodeJS.ErrnoException).code==='ENOENT')return undefined; throw error; }
  const data=JSON.parse(body) as Journal;
  if(data.version!==1)throw new Error(`Unsupported journal version ${data.version}`);
  return data;
}
export async function writeJournal(path:string,state:Journal):Promise<void> {
  await mkdir(dirname(path),{recursive:true,mode:0o700});
  const temporary=join(dirname(path),`.resume-${randomUUID()}.tmp`);
  const file=await open(temporary,'wx',0o600);
  try { await file.writeFile(JSON.stringify(state)+'\n'); await file.sync(); }
  finally { await file.close(); }
  try { await rename(temporary,path); }
  catch(error) { await unlink(temporary).catch(()=>{}); throw error; }
}

