import { createHash } from 'node:crypto';
import { createReadStream } from 'node:fs';
import { stat } from 'node:fs/promises';
import { CliError } from './types.ts';
export async function fingerprint(path:string,signal:AbortSignal) {
  const before=await stat(path,{bigint:true});
  const hash=createHash('sha256');
  for await(const chunk of createReadStream(path,{signal}))hash.update(chunk);
  const after=await stat(path,{bigint:true});
  if(before.size!==after.size||before.mtimeNs!==after.mtimeNs)throw new CliError('Source changed while hashing','source_changed');
  return {size:Number(after.size),mtimeNs:String(after.mtimeNs),sha256:hash.digest('hex')};
}
export async function readPart(path:string,offset:number,length:number,signal:AbortSignal) {
  const chunks:Buffer[]=[];
  for await(const chunk of createReadStream(path,{start:offset,end:offset+length-1,signal}))chunks.push(Buffer.from(chunk));
  const body=Buffer.concat(chunks);
  if(body.length!==length)throw new CliError('Source became shorter','source_changed');
  return {body,sha256:createHash('sha256').update(body).digest('hex')};
}

