import { CliError } from './types.ts';
export function destinationKey(url:URL):string {
  const result=new URL(url);
  result.username='';result.password='';result.search='';result.hash='';
  if(!result.pathname.endsWith('/'))result.pathname+='/';
  return result.toString();
}
export function objectPath(relativePath:string):string {
  const parts=relativePath.split('/');
  if(parts.some(part=>!part||part==='.'||part==='..'))throw new CliError('Invalid source path','invalid_path');
  return parts.map(encodeURIComponent).join('/');
}
export function endpoint(base:URL,path:string):URL {return new URL(path,new URL(destinationKey(base)));}
export function validateDestination(url:URL):void {
  if(!['http:','https:'].includes(url.protocol))throw new CliError('Destination must use HTTP or HTTPS','invalid_destination');
  if(url.username||url.password)throw new CliError('Credentials in destination URL unsupported','invalid_destination');
}

