import { CliError } from './types.ts';
export function matchesFile(saved:JournalFile,file:Fingerprint,chunkBytes:number):boolean {
  return saved.size===file.size&&saved.mtimeNs===file.mtimeNs&&saved.sha256===file.sha256&&saved.chunkBytes===chunkBytes;
}
export function validateParts(value:unknown,size:number,chunkBytes:number):JournalPart[] {
  if(!Array.isArray(value))throw new CliError('Invalid parts response','invalid_response');
  const total=Math.ceil(size/chunkBytes),seen=new Set<number>(),parts:JournalPart[]=[];
  for(const raw of value) {
    if(!raw||typeof raw!=='object')throw new CliError('Malformed part','invalid_response');
    const part=raw as JournalPart;
    const expected=part.number===total?size-(part.number-1)*chunkBytes:chunkBytes;
    if(!Number.isInteger(part.number)||part.number<1||part.number>total||seen.has(part.number)||part.bytes!==expected||!/^[0-9a-f]{64}$/.test(part.sha256))throw new CliError('Inconsistent part list','invalid_response');
    seen.add(part.number);parts.push(part);
  }
  return parts.sort((a,b)=>a.number-b.number);
}

