import { retry } from './retry.ts';
import { endpoint } from './path.ts';
export class HttpError extends Error {
  status:number;code:string;retryAfter?:string;
  constructor(status:number,code:string,after?:string){super(`HTTP ${status} while uploading`);this.status=status;this.code=code;this.retryAfter=after;}
}
export class Transport {
  private base:URL;private token?:string;private options:RetryOptions;
  constructor(base:URL,token:string|undefined,options:RetryOptions){this.base=base;this.token=token;this.options=options;}
  async request(path:string,method:string,body?:BodyInit,extra?:HeadersInit):Promise<Response> {
    const headers=new Headers(extra);if(this.token)headers.set('authorization',`Bearer ${this.token}`);
    const response=await fetch(endpoint(this.base,path),{method,body,headers,signal:this.options.signal,redirect:'error'});
    if(!response.ok){const data=await response.json().catch(()=>undefined) as any;throw new HttpError(response.status,data?.error?.code??'http_error',response.headers.get('retry-after')??undefined);}
    return response;
  }
  async uploadPart(id:string,number:number,body:Buffer,sha256:string):Promise<void> {
    await retry(async()=>{const response=await this.request(`uploads/${encodeURIComponent(id)}/parts/${number}`,'PUT',new Uint8Array(body),{'content-length':String(body.length),'x-part-sha256':sha256});await response.body?.cancel();},
      error=>error instanceof HttpError?{retry:[408,429,500,502,503,504].includes(error.status),after:error.retryAfter}:{retry:error instanceof TypeError},this.options);
  }
  async getStatus(id:string){return(await this.request(`uploads/${encodeURIComponent(id)}`,'GET')).json();}
  async begin(data:unknown){return(await this.request('uploads','POST',JSON.stringify(data),{'content-type':'application/json'})).json();}
  async complete(id:string,data:unknown){return(await this.request(`uploads/${encodeURIComponent(id)}/complete`,'POST',JSON.stringify(data),{'content-type':'application/json'})).json();}
}

