test("empty-file: zero part requests; empty SHA-256 receipt", async () => {
  const fixture = await createScenario({
    seed: 1847, rootPrefix: 'driftship-empty-file-', tenant: '/tenant-blue/',
    files: [{ path: "empty.marker", bytes: 0, expectedSha256: '467e4079172dd80a8ee707c22d506921c74838162cf5f05fe85917d2f2e32cfc' }],
    fault: { kind: 'none', occurrence: 1 },
    settings: { concurrency: 4, chunkBytes: 4194304, retries: 4 },
  });
  try {
    const result = await fixture.run(['push', fixture.directory, '--to', fixture.url, '--json']);
    const requests = fixture.requests();
    const events = result.stdout.trim().split('\n').filter(Boolean).map(line => JSON.parse(line));
    assert.equal(result.outcome, 'complete');
    assert.ok(requests.every(request => request.path.startsWith('/tenant-blue/')));
    assert.ok(requests.every(request => request.method !== 'DELETE'));
    assert.ok(!result.stdout.includes(fixture.bearerToken));
    assert.ok(!result.stderr.includes(fixture.bearerToken));
    const receipt = fixture.object("empty.marker");
    assert.equal(receipt.bytes, 0);
    assert.equal(receipt.sha256, '467e4079172dd80a8ee707c22d506921c74838162cf5f05fe85917d2f2e32cfc');
    const completion = events.findLast(event => event.type === 'complete');
    assert.equal(completion.bytes, 0);
    assert.equal(completion.uploaded_bytes + completion.resumed_bytes, 0);
    assert.ok(fixture.peakActiveParts() <= 4);
    const journal = await readJournal(fixture.journalPath);
    assert.equal(journal.files["empty.marker"].receipt.sha256, receipt.sha256);
  } finally { await fixture.close(); }
});

