export function validateReceipt(value:unknown,file:JournalFile):Receipt {
  if(!value||typeof value!=='object')throw new CliError('Missing receipt','invalid_response');
  const receipt=value as Receipt;
  if(receipt.path!==file.path||receipt.bytes!==file.size||receipt.sha256!==file.sha256||typeof receipt.etag!=='string'||!receipt.etag)throw new CliError('Receipt does not match source','invalid_response');
