}
export async function completeFile(transport:Transport,file:JournalFile):Promise<Receipt> {
  try {return validateReceipt(await transport.complete(file.uploadId,{parts:file.parts.map(p=>({number:p.number,sha256:p.sha256})),sha256:file.sha256}),file);}
  catch(error) {
    if(error instanceof HttpError||!(error instanceof TypeError))throw error;
    const status=await transport.getStatus(file.uploadId);
    if(status.state!=='complete')throw error;
    return validateReceipt(status.receipt,file);
  }
}

