export class TransferMetrics {
  private confirmed=new Set<string>();private uploadedBytes=0;private resumedBytes=0;private files:number;private bytes:number;
  constructor(files:number,bytes:number){this.files=files;this.bytes=bytes;}
  confirm(path:string,part:number,bytes:number,resumed:boolean):void {
    const key=JSON.stringify([path,part]);if(this.confirmed.has(key))return;this.confirmed.add(key);
    if(resumed)this.resumedBytes+=bytes;else this.uploadedBytes+=bytes;
  }
  receipt(path:string,bytes:number,resumed:boolean){this.confirm(path,0,bytes,resumed);}
  snapshot(){return{files:this.files,bytes:this.bytes,uploadedBytes:this.uploadedBytes,resumedBytes:this.resumedBytes};}
}

